ucl_unescape_json_string (char *str, size_t len)
{
        char *t = str, *h = str;
        int i, uval;

        if (len <= 1) {
                return len;
        }
        /* t is target (tortoise), h is source (hare) */

        while (len) {
                if (*h == '\\') {
                        h ++;

                        if (len == 1) {
                                /*
                                 * If \ is last, then do not try to go further
                                 * Issue: #74
                                 */
                                len --;
                                *t++ = '\\';
                                continue;
                        }

                        switch (*h) {
                        case 'n':
                                *t++ = '\n';
                                break;
                        case 'r':
                                *t++ = '\r';
                                break;
                        case 'b':
                                *t++ = '\b';
                                break;
                        case 't':
                                *t++ = '\t';
                                break;
                        case 'f':
                                *t++ = '\f';
                                break;
                        case '\\':
                                *t++ = '\\';
                                break;
                        case '"':
                                *t++ = '"';
                                break;
                        case 'u':
                                /* Unicode escape */
                                uval = 0;
                                h ++; /* u character */
                                len --;

                                if (len > 3) {
                                        for (i = 0; i < 4; i++) {
                                                uval <<= 4;
                                                if (isdigit (h[i])) {
                                                        uval += h[i] - '0';
                                                }
                                                else if (h[i] >= 'a' && h[i] <= 'f') {
                                                        uval += h[i] - 'a' + 10;
                                                }
                                                else if (h[i] >= 'A' && h[i] <= 'F') {
                                                        uval += h[i] - 'A' + 10;
                                                }
                                                else {
                                                        break;
                                                }
