                                                t[0] = (char)uval;
                                                t ++;
                                        }
                                        else if(uval < 0x800) {
                                                t[0] = 0xC0 + ((uval & 0x7C0) >> 6);
                                                t[1] = 0x80 + ((uval & 0x03F));
